function materialCatalogChapter(n,s){const ids=[...new Set(TC.placements.filter(p=>p.source_id===s.book&&p.chapter_number===n).map(p=>p.kanji_id))];const symbols=ids.map(id=>TC.kanji.find(k=>k.id===id)?.symbol).filter(Boolean);return CatalogSelection.chapterCard({number:n,label:`${t('chapter')} ${n}`,counts:`${ids.length} ${t('kanji')}`,preview:`<span class="p-book-kanji-row">${symbols.slice(0,8).map(c=>`<span lang="ja">${escapeHTML(c)}</span>`).join('')}</span>`,select:true,selected:(s.chapters||[]).includes(n),html:escapeHTML});}
