 const s=sourceDraft,type=materialType(s);
 return `<div class="recipe-editor-screen">${header(t(sourceIndex===null?'addSource':'editSource'),'recipe-editor',type==='kanji'?`<button type="button" class="icon-button" data-kanji-search aria-label="${t('search')}" aria-expanded="${materialKanjiSearchOpen}">${icon('search')}</button>`:'')}<div class="recipe-content source-picker recipe-source-content"><fieldset class="material-types"><legend>${t('materialType')}</legend><div>${materialTypes.map(key=>`<label><input type="radio" name="material-type" data-material-type="${key}" ${key===type?'checked':''}><span>${t(materialTypeKeys[key])}</span></label>`).join('')}</div><p class="material-type-hint">${t(materialTypeHints[type])}</p></fieldset><section class="material-fields" data-material-form="${type}">${materialFields[type](s)}</section>${recipeWordsLink(sourceWords(s).length,true)}<p id="source-error" class="form-error" role="alert"></p></div><div class="recipe-editor-footer"><button type="button" class="recipe-save-fab" data-tr="source-apply">${t(sourceIndex===null?'add':'updateMaterial')}</button></div></div>`;
